export const WHAT_IS_AI_ACTIVITIES = [
{n:1,type:"mcq",micro:"Komputer mengikuti instruksi",q:"Pada dasarnya, komputer biasa bekerja dengan cara...",options:["Mengikuti langkah-langkah instruksi yang dibuat manusia, dengan sangat cepat dan teliti","Menebak-nebak jawaban secara acak lalu berharap hasilnya kebetulan benar","Berpikir sendiri seperti manusia, dengan perasaan dan keinginan pribadi untuk memilih"],answer:0,explain:"Komputer menjalankan program: daftar instruksi yang ditulis manusia. Ia cepat dan patuh, tapi tidak punya kehendak sendiri.",hint:"Siapa yang menulis langkah-langkah yang dijalankan komputer?"},
{n:2,type:"mcq",micro:"Apa itu AI",q:"Yang membuat sebuah program disebut 'AI' (kecerdasan buatan) biasanya adalah kemampuannya untuk...",options:["Terhubung ke internet dan punya layar besar yang menampilkan banyak gambar berwarna, sehingga langsung disebut AI oleh pembuatnya","Mengerjakan tugas yang biasanya butuh kecerdasan manusia, seperti mengenali gambar atau bahasa, sering dengan belajar dari contoh","Berjalan lebih cepat daripada program lain karena dipasang di komputer yang mahal, meskipun hanya menjalankan perintah satu per satu"],answer:1,explain:"AI adalah istilah untuk program yang melakukan hal-hal yang dahulu hanya bisa dilakukan manusia: melihat, mendengar, memahami bahasa, mengambil keputusan.",hint:"AI mencoba meniru tugas-tugas 'pintar' yang biasa dilakukan manusia."},
{n:3,type:"mcq",micro:"AI di sekitar kita",q:"Manakah yang paling mungkin menggunakan AI?",options:["Jam dinding yang berputar mengikuti baterainya","Lampu meja yang menyala saat tombolnya ditekan","Aplikasi yang mengubah ucapanmu menjadi tulisan"],answer:2,explain:"Mengubah suara menjadi teks butuh mengenali pola bunyi bahasa — tugas yang biasanya diselesaikan dengan AI. Kalkulator dan saklar hanya mengikuti aturan tetap sederhana.",hint:"Mana yang harus 'menebak' apa yang kamu maksud?"},
{n:4,type:"tf",micro:"AI dibuat manusia",q:"Benar atau Salah: Sistem AI dirancang dan dilatih oleh manusia.",answer:true,explain:"AI tidak muncul dengan sendirinya. Manusia memilih tujuannya, mengumpulkan datanya, dan melatih serta mengujinya.",hint:"Dari mana sebuah program berasal?"},
{n:5,type:"mcq",micro:"AI bukan manusia",q:"Ketika asisten suara menjawab 'Selamat pagi, semoga harimu menyenangkan', itu berarti...",options:["Asisten itu menghasilkan kalimat yang cocok dengan pola sapaan, tanpa benar-benar merasakan apa pun","Ada orang sungguhan yang bersembunyi di dalam perangkat dan menjawabmu secara langsung","Asisten itu benar-benar peduli, ikut merasa senang, dan menyayangi perasaanmu setiap pagi"],answer:0,explain:"AI menghasilkan respons yang tampak ramah karena dilatih dari contoh bahasa manusia, bukan karena punya perasaan.",hint:"Apakah program bisa benar-benar merasa senang atau sedih?"},
{n:6,type:"mcq",micro:"Contoh AI: rekomendasi",q:"Saat aplikasi musik menyarankan lagu 'yang mungkin kamu suka', ia bekerja dengan...",options:["Membaca pikiran dan suasana hatimu lewat ponsel, lalu memilih lagu yang sedang kamu bayangkan","Mencari pola dari lagu yang kamu dan orang lain dengar sebelumnya, lalu menebak yang mirip","Memilih lagu secara acak dari seluruh daftar tanpa memperhatikan lagu yang pernah kamu dengar"],answer:1,explain:"Sistem rekomendasi mempelajari pola pilihan banyak orang dan menebak apa yang cocok untukmu.",hint:"Data apa yang dimiliki aplikasi tentang kebiasaan mendengarmu?"},
{n:7,type:"mcq",micro:"Contoh AI: filter spam",q:"Kotak email memindahkan pesan iklan mencurigakan ke folder 'Spam'. Ini contoh AI yang...",options:["Menghapus email yang masuk secara acak tanpa melihat isi atau pengirimnya, sehingga pesan penting ikut hilang","Menulis balasan baru untukmu tanpa diminta lalu mengirimkannya ke daftar kontakmu setiap kali ada email","Mengklasifikasikan pesan menjadi 'spam' atau 'bukan spam' berdasarkan contoh yang pernah dipelajarinya"],answer:2,explain:"Filter spam adalah pengklasifikasi: ia belajar dari jutaan contoh email yang ditandai orang sebagai spam / bukan spam.",hint:"Apa dua kotak tempat email dipilah?"},
{n:8,type:"order",micro:"Bagaimana AI dipakai",q:"Urutkan langkah umum saat kamu menggunakan sebuah fitur AI, misalnya penerjemah bahasa.",items:["Kamu memberi masukan (kalimat yang ingin diterjemahkan)","AI memproses masukan itu menggunakan pola yang sudah dipelajarinya","AI memberi keluaran (kalimat terjemahan) yang merupakan tebakan terbaiknya"],answer:[0,1,2],explain:"Pola dasar semua AI: masukan → pemrosesan oleh model → keluaran berupa prediksi/tebakan.",hint:"Kamu memberi sesuatu dulu, baru AI menjawab."},
{n:9,type:"mcq",micro:"AI bisa salah",q:"Sebuah aplikasi kamera menandai seekor anak anjing sebagai 'kucing'. Ini menunjukkan...",options:["AI bisa membuat kesalahan, terutama kalau contoh latihannya kurang atau gambarnya membingungkan","Anjing dan kucing sebenarnya hewan yang sama, jadi boleh diberi nama apa saja","Anak anjing itu memang kucing yang masih kecil, sehingga hasil AI dianggap benar"],answer:0,explain:"AI menebak berdasarkan pola. Kalau polanya mirip atau datanya terbatas, tebakannya bisa keliru.",hint:"Apakah 'tebakan terbaik' selalu berarti 'tebakan benar'?"},
{n:10,type:"mcq",micro:"AI vs program biasa",q:"Perbedaan utama antara program biasa dan program AI yang belajar adalah...",options:["Program biasa hanya berjalan di komputer meja besar; AI yang belajar hanya bisa dijalankan di ponsel dan jam tangan pintar","Program biasa mengikuti aturan yang ditulis langsung; AI yang belajar menemukan polanya sendiri dari banyak contoh","Program biasa menemukan polanya sendiri dari banyak contoh; AI yang belajar mengikuti aturan yang ditulis langsung"],answer:1,explain:"Alih-alih menulis semua aturan, pembuat AI memberi banyak contoh dan membiarkan program menyimpulkan polanya.",hint:"Siapa yang membuat 'aturan' pada masing-masing: manusia langsung, atau program dari contoh?"},
{n:11,type:"mcq",micro:"Contoh AI: buka kunci wajah",q:"Ponsel yang terbuka saat 'melihat' wajah pemiliknya menggunakan AI untuk...",options:["Mengganti wallpaper layar secara otomatis setiap kali pemiliknya mendekat","Memotret wajahmu lalu mengunggahnya ke internet agar dilihat banyak orang","Mengenali apakah wajah di kamera cocok dengan pola wajah yang terdaftar"],answer:2,explain:"Pengenalan wajah membandingkan pola dari kamera dengan pola wajah yang disimpan saat pendaftaran.",hint:"Apa yang dibandingkan: wajah sekarang dengan wajah yang mana?"},
{n:12,type:"tf",micro:"AI tidak 'memahami' seperti manusia",q:"Benar atau Salah: Ketika AI penerjemah mengubah 'kucing' menjadi 'cat', ia benar-benar tahu seperti apa rasanya membelai kucing.",answer:false,explain:"AI memetakan kata ke kata dan pola ke pola. Ia tidak punya pengalaman atau pemahaman seperti manusia.",hint:"Apakah program pernah menyentuh kucing?"},
{n:13,type:"mcq",micro:"AI sebagai alat",q:"Cara paling tepat memandang AI adalah sebagai...",options:["Alat buatan manusia yang berguna untuk tugas tertentu, dengan kelebihan dan keterbatasan","Sihir modern yang sulit dijelaskan, sehingga cara kerjanya hanya dipahami oleh para ahli","Makhluk hidup baru yang punya perasaan dan keinginan sendiri seperti manusia dan hewan"],answer:0,explain:"Seperti kalkulator atau mesin cuci, AI adalah alat. Ia sangat berguna untuk hal tertentu tapi bukan pengganti penilaian manusia.",hint:"Palu, kalkulator, AI — apa kesamaannya?"},
{n:14,type:"mcq",micro:"AI butuh contoh",q:"Untuk membuat AI yang mengenali buah mangga dari foto, hal yang paling dibutuhkan adalah...",options:["Satu foto mangga yang bagus, lalu AI langsung mengenali mangga dari berbagai sudut","Banyak sekali foto mangga (dan foto bukan-mangga) supaya AI belajar ciri-cirinya","Nama buah mangga yang diketik dengan benar, supaya AI otomatis tahu rupa mangga"],answer:1,explain:"AI belajar dari banyak contoh. Semakin banyak dan beragam contohnya, semakin baik ia mengenali hal baru.",hint:"Bagaimana anak kecil belajar mengenali mangga — dari satu kali lihat atau berkali-kali?"},
{n:15,type:"mcq",micro:"Contoh AI: game",q:"Musuh dalam gim video yang 'mengejar' pemain dengan cerdik...",options:["Dikendalikan oleh pemain lain yang diam-diam duduk di balik layar dan menggerakkan musuhnya","Harus memakai AI canggih yang belajar dari jutaan contoh, dan tidak bisa memakai aturan sederhana","Bisa memakai aturan sederhana ('kejar suara terdekat') ATAU AI, tergantung dibuatnya bagaimana"],answer:2,explain:"Tidak semua perilaku 'pintar' adalah AI yang belajar. Banyak gim memakai aturan yang dirancang tangan yang tetap terasa cerdas.",hint:"Apakah perilaku cerdas selalu berarti 'belajar dari data'?"},
{n:16,type:"mcq",micro:"AI menebak, bukan memastikan",q:"Ketika aplikasi cuaca berkata 'kemungkinan hujan 70%', AI-nya sedang...",options:["Memberi perkiraan berdasarkan pola cuaca yang mirip di masa lalu","Mengendalikan awan dan angin supaya hujan turun sesuai angka di layar","Memastikan hujan turun tepat pada jam yang tertera di aplikasi"],answer:0,explain:"AI prediksi memberi kemungkinan, bukan kepastian. '70%' berarti pada situasi seperti ini, hujan turun sekitar 7 dari 10 kali.",hint:"Apa arti angka persen pada ramalan?"},
{n:17,type:"tf",micro:"AI ada di banyak tempat",q:"Benar atau Salah: AI hanya ada di robot berbentuk manusia.",answer:false,explain:"Kebanyakan AI tidak berbentuk apa pun — ia berupa program di dalam aplikasi: pencarian, peta, kamera, email, media sosial.",hint:"Pernahkah kamu memakai AI hari ini tanpa melihat robot?"},
{n:18,type:"mcq",micro:"Siapa yang bertanggung jawab",q:"Jika mobil dengan fitur AI melakukan kesalahan, siapa yang tetap bertanggung jawab atas cara AI itu dibuat dan digunakan?",options:["AI itu sendiri, karena ia yang mengambil keputusan dan menggerakkan mobilnya","Manusia — perancang, perusahaan pembuat, dan pengguna yang mengawasinya","Mobil itu saja, sebab hanya mesin yang bergerak dan menyetir di jalan"],answer:1,explain:"AI bukan pribadi hukum. Tanggung jawab tetap pada manusia dan lembaga yang merancang, menjual, dan menggunakannya.",hint:"Bisakah sebuah alat dimintai pertanggungjawaban?"},
{n:19,type:"mcq",micro:"AI vs pencarian internet",q:"Bertanya ke mesin pencari biasa berbeda dari bertanya ke AI percakapan karena mesin pencari umumnya...",options:["Menyusun jawaban kalimat baru dari awal dengan meniru gaya bicara orang, bukan menunjukkan tautan","Hanya berjalan tanpa internet dan menyimpan seluruh halaman web di dalam ponsel milikmu sendiri","Menunjukkan daftar tautan ke halaman yang sudah ada, bukan menyusun jawaban kalimat sendiri"],answer:2,explain:"Mesin pencari mengambil halaman yang relevan; AI percakapan menyusun kalimat baru sebagai jawaban. Keduanya berguna untuk hal berbeda.",hint:"Apa yang kamu terima: daftar tautan, atau paragraf yang ditulis untukmu?"},
{n:20,type:"open",micro:"AI dalam hidupku",q:"Sebutkan dua fitur atau aplikasi yang kamu pakai yang kemungkinan menggunakan AI, dan jelaskan tugas 'pintar' apa yang dikerjakan masing-masing.",explain:"Jawaban baik menyebut fitur nyata DAN tugas kecerdasan yang dilakukannya (mengenali, memprediksi, merekomendasikan, mengklasifikasi).",hint:"Pikirkan: papan ketik, kamera, peta, media sosial, toko daring, email.",sample:"Contoh: (1) Papan ketik ponsel yang menyarankan kata berikutnya — tugasnya memprediksi kata yang paling mungkin kamu ketik. (2) Aplikasi peta yang memperkirakan waktu tempuh dan jalur tercepat — tugasnya memprediksi kondisi lalu lintas dari data pergerakan banyak pengguna."},
{n:21,type:"mcq",micro:"Aturan vs contoh",q:"Cara A: 'Jika buah berwarna kuning dan panjang melengkung, sebut pisang.' Cara B: tunjukkan 5.000 foto pisang sampai program menyimpulkan sendiri cirinya. Cara B adalah pendekatan...",options:["Pembelajaran mesin (machine learning) — belajar pola dari contoh","Pencarian di internet — program menyalin jawaban dari web","Berbasis aturan (rule-based) — pola ditulis manusia"],answer:0,explain:"Pembelajaran mesin menyimpulkan aturan dari banyak contoh, alih-alih menerima aturan yang ditulis manusia satu per satu.",hint:"Cara mana yang aturannya ditemukan oleh program itu sendiri?"},
{n:22,type:"mcq",micro:"Data latih",q:"'Data latih' (training data) sebuah AI adalah...",options:["Kabel dan alat penghubung yang dipakai untuk menyambung komputer ke internet","Kumpulan contoh yang dipakai untuk mengajari AI mengenali pola","Nama merek dan tipe komputer yang dipakai untuk menjalankan program AI"],answer:1,explain:"Data latih adalah 'buku pelajaran' AI: contoh-contoh (dan sering jawabannya) yang darinya AI belajar.",hint:"Dari apa AI 'belajar'?"},
{n:23,type:"mcq",micro:"Label",q:"Untuk melatih AI membedakan foto 'anjing' dan 'kucing', tiap foto latih biasanya diberi...",options:["Harga jual yang tertera pada setiap foto di toko daring","Bingkai emas yang membuat foto terlihat lebih bagus di layar","Label yang menyatakan jawaban benar ('anjing' atau 'kucing')"],answer:2,explain:"Label adalah jawaban benar yang menyertai contoh, sehingga AI bisa memeriksa dan memperbaiki tebakannya saat berlatih.",hint:"Bagaimana AI tahu tebakannya benar atau salah saat latihan?"},
{n:24,type:"mcq",micro:"Pola",q:"Inti dari kebanyakan AI adalah menemukan...",options:["Pola dalam data yang bisa dipakai untuk menebak hal baru","Warna favorit pengguna supaya tampilan layar sesuai selera","Cara tercepat memadamkan listrik di sebuah gedung besar"],answer:0,explain:"AI mencari keteraturan (pola) pada data lama, lalu menerapkannya untuk memperkirakan data yang belum pernah dilihat.",hint:"Apa yang dicari AI di dalam ribuan contoh?"},
{n:25,type:"mcq",micro:"Masukan dan keluaran",q:"Pada AI pengenal tulisan tangan: yang menjadi MASUKAN dan KELUARAN berturut-turut adalah...",options:["Keduanya berupa angka yang diketik pengguna lewat papan tombol ponsel","Masukan: gambar coretan angka; Keluaran: angka yang dikenali (misalnya '7')","Masukan: angka '7' yang diketik; Keluaran: gambar coretan yang menyerupainya"],answer:1,explain:"Masukan adalah data mentah yang diberikan; keluaran adalah hasil/prediksi AI.",hint:"Apa yang kamu beri, dan apa yang kamu dapat kembali?"},
{n:26,type:"classify",micro:"Data latih vs model vs prediksi",q:"Kelompokkan tiap hal ke 'Data latih', 'Model (hasil belajar)', atau 'Prediksi (keluaran)'.",items:["10.000 foto hewan yang sudah diberi nama jenisnya","Program hasil pelatihan yang bisa menebak jenis hewan dari foto baru","Jawaban 'kemungkinan besar ini rusa' untuk sebuah foto"],groups:["Data latih","Model","Prediksi"],answer:{"Data latih":["10.000 foto hewan yang sudah diberi nama jenisnya"],"Model":["Program hasil pelatihan yang bisa menebak jenis hewan dari foto baru"],"Prediksi":["Jawaban 'kemungkinan besar ini rusa' untuk sebuah foto"]},explain:"Data latih dipakai untuk membuat model; model dipakai untuk menghasilkan prediksi.",hint:"Bahan mentah → alat yang terbentuk → hasil yang keluar."},
{n:27,type:"tf",micro:"Lebih banyak contoh sering membantu",q:"Benar atau Salah: Setelah AI diberi beberapa contoh, menambah lebih banyak contoh yang beragam dan berkualitas hampir tidak berpengaruh pada keandalan prediksinya.",answer:false,explain:"Justru berpengaruh besar. Contoh yang lebih banyak dan beragam membantu AI menangkap pola yang benar dan menghindari kesimpulan yang terlalu sempit.",hint:"Belajar dari 5 contoh atau 5.000 contoh — mana yang biasanya lebih kuat?"},
{n:28,type:"mcq",micro:"Keyakinan (confidence)",q:"AI mengeluarkan 'anjing: 92%, serigala: 7%, rubah: 1%'. Angka-angka ini menunjukkan...",options:["Harga yang pantas untuk membeli masing-masing hewan","Berat badan perkiraan masing-masing hewan di foto","Seberapa yakin AI terhadap tiap kemungkinan jawaban"],answer:2,explain:"Banyak AI memberi skor keyakinan untuk tiap kemungkinan. Skor tinggi bukan jaminan benar, tapi menunjukkan tebakan teratasnya.",hint:"Angka 92% itu mengukur apa?"},
{n:29,type:"mcq",micro:"Keyakinan tinggi bisa tetap salah",q:"Jika AI berkata '99% yakin ini kucing' padahal itu kelinci, artinya...",options:["AI bisa sangat yakin DAN tetap keliru, misalnya karena datanya bias atau gambarnya tak biasa","Kelinci itu sebenarnya kucing yang kecil, jadi AI tidak keliru dan orang harus menerimanya","Keyakinan 99% menandakan jawaban AI terjamin benar, jadi hewan itu memang seekor kucing biasa"],answer:0,explain:"Keyakinan tinggi hanya berarti pola masukan sangat cocok dengan apa yang dipelajari AI — bukan jaminan kebenaran.",hint:"Bisakah seseorang salah sambil merasa sangat yakin?"},
{n:30,type:"order",micro:"Melatih sebuah AI sederhana",q:"Urutkan langkah membuat AI yang mengenali email spam.",items:["Kumpulkan banyak email dan tandai tiap satu sebagai 'spam' atau 'bukan spam'","Latih model dengan contoh-contoh berlabel itu","Uji model pada email baru yang belum pernah dilihatnya untuk mengukur ketepatannya","Pakai model untuk memilah email yang masuk setiap hari"],answer:[0,1,2,3],explain:"Kumpulkan & beri label → latih → uji → gunakan. Menguji pada data baru penting agar tahu model benar-benar belajar, bukan sekadar menghafal.",hint:"Kamu tidak bisa melatih sebelum punya contoh berlabel."},
{n:31,type:"mcq",micro:"Menghafal vs belajar pola",q:"Sebuah AI mengenali sempurna semua foto latihnya tapi kacau pada foto baru. Ini disebut...",options:["Belajar dengan sangat baik sehingga bekerja sempurna pada foto-foto yang baru","Overfitting — AI 'menghafal' contoh latih alih-alih menangkap pola umum","Prediksi sempurna yang tidak perlu diuji dengan foto yang belum dilihat"],answer:1,explain:"Overfitting: model terlalu pas pada data latih sehingga gagal menggeneralisasi ke data baru. Inilah alasan kita menguji dengan data terpisah.",hint:"Hafal jawaban soal latihan vs paham konsepnya — mana yang gagal saat soal diganti?"},
{n:32,type:"mcq",micro:"Generalisasi",q:"'Generalisasi' pada AI berarti kemampuan...",options:["Menjadi umum dan membosankan karena semua jawabannya dibuat seragam dan tidak bervariasi lagi","Menghafal seluruh isi internet sampai tidak ada satu pun data yang belum pernah dilihat","Menebak dengan baik pada data baru yang belum pernah dilihat, bukan hanya data latih"],answer:2,explain:"Tujuan pelatihan adalah model yang menggeneralisasi: bekerja baik di dunia nyata, bukan hanya pada contoh yang dipakai berlatih.",hint:"Untuk apa AI dibuat — mengingat contoh lama atau menghadapi kasus baru?"},
{n:33,type:"tf",micro:"AI belajar dari data, bukan pengalaman hidup",q:"Benar atau Salah: AI gambar belajar seperti apa 'pantai' dari ribuan foto berlabel, bukan dari pernah berlibur ke pantai.",answer:true,explain:"Sumber 'pengetahuan' AI adalah data yang diberikan manusia, bukan pengalaman langsung di dunia.",hint:"Pernahkah program merasakan pasir di kakinya?"},
{n:34,type:"mcq",micro:"Kualitas data",q:"Jika separuh foto 'burung' pada data latih sebenarnya foto pesawat yang salah label, model akan...",options:["Belajar pola yang keliru dan sering salah membedakan burung dan pesawat","Menolak berlatih karena fotonya terlalu banyak, lalu berhenti bekerja","Tetap sempurna karena jumlah foto yang banyak menutupi kesalahan labelnya"],answer:0,explain:"Label yang salah mengajari pola yang salah. Kualitas data latih sangat menentukan kualitas model.",hint:"Kalau buku pelajaranmu penuh jawaban salah, apa yang kamu pelajari?"},
{n:35,type:"mcq",micro:"Fitur",q:"'Fitur' (feature) dalam pembelajaran mesin adalah...",options:["Iklan produk yang muncul di layar saat aplikasi AI dibuka, misalnya gambar, tombol, atau warna","Ciri terukur dari data yang dipakai model untuk membuat keputusan, misalnya tinggi, warna, jumlah kata","Tombol yang ditekan pengguna di aplikasi untuk memulai pelatihan, misalnya mulai, jeda, atau ulangi"],answer:1,explain:"Fitur adalah potongan informasi yang jadi bahan pertimbangan model — misalnya untuk menebak harga rumah: luas, jumlah kamar, lokasi.",hint:"Informasi apa saja yang 'dilihat' model untuk memutuskan?"},
{n:36,type:"mcq",micro:"AI prediksi teks",q:"Papan ketik yang menyarankan kata berikutnya bekerja dengan memprediksi...",options:["Isi pikiran temanmu yang sedang duduk di dekatmu, berdasarkan ekspresi wajah dan kebiasaannya","Kata yang paling panjang di kamus, lalu menampilkannya setiap kali kamu mengetik satu huruf","Kata apa yang paling sering muncul setelah kata-kata yang sudah kamu ketik, berdasarkan pola bahasa"],answer:2,explain:"Model bahasa memperkirakan kata berikutnya yang paling mungkin dari pola teks yang sangat banyak.",hint:"Setelah 'Selamat pagi', kata apa yang biasanya menyusul?"},
{n:37,type:"tf",micro:"AI tidak punya niat",q:"Benar atau Salah: Kalau AI merekomendasikan video yang membuatmu menonton berjam-jam, itu karena AI 'ingin' kamu kecanduan.",answer:false,explain:"AI tidak punya keinginan. Namun, ia bisa dilatih dengan TUJUAN yang dipilih manusia (misalnya 'perpanjang waktu tonton'), dan itulah yang perlu kita cermati — pilihannya ada pada perancangnya.",hint:"Siapa yang menetapkan tujuan yang dikejar AI?"},
{n:38,type:"mcq",micro:"Masukan buruk, keluaran buruk",q:"Prinsip 'sampah masuk, sampah keluar' (garbage in, garbage out) pada AI berarti...",options:["Kalau data atau pertanyaan yang diberikan buruk atau menyesatkan, hasilnya juga cenderung buruk","AI harus dibuang dan diganti dengan yang baru setiap tahun supaya tidak menumpuk sampah","AI benar-benar mengeluarkan sampah fisik berupa kotak dan plastik dari dalam komputernya"],answer:0,explain:"Kualitas keluaran AI dibatasi oleh kualitas masukannya — baik data latih maupun pertanyaan pengguna.",hint:"Bisakah jawaban bagus keluar dari data yang berantakan?"},
{n:39,type:"mcq",micro:"Model",q:"Setelah pelatihan selesai, 'model' pada dasarnya adalah...",options:["Seorang manusia kecil di dalam komputer yang membaca pertanyaan lalu menjawabnya","Sekumpulan angka dan pola tersimpan yang mengubah masukan menjadi prediksi","Sebuah situs web berisi jawaban tertulis yang disalin ke layar saat dibutuhkan"],answer:1,explain:"Model adalah hasil belajar: struktur berisi bilangan (parameter) yang menangkap pola dari data latih.",hint:"Apa yang tersisa setelah AI selesai 'belajar'?"},
{n:40,type:"open",micro:"Merancang data latih",q:"Kamu ingin membuat AI yang mengenali daun sehat vs daun berpenyakit untuk membantu petani. Data latih seperti apa yang kamu butuhkan, dan satu cara data yang buruk bisa menyesatkan model?",explain:"Jawaban baik menyebut keberagaman contoh, label yang benar, dan contoh bias yang membuat model menangkap pola yang salah.",hint:"Apa yang tanpa sengaja bisa 'selalu berbeda' antara kedua kelompok fotomu?",sample:"Butuh: banyak foto daun sehat DAN daun berpenyakit, dari berbagai jenis tanaman, kondisi cahaya, dan tingkat keparahan, masing-masing diberi label benar oleh ahli. Data buruk: jika semua foto 'sehat' diambil siang hari cerah dan semua foto 'sakit' diambil sore hari redup, model bisa keliru belajar bahwa 'gelap = sakit' alih-alih melihat kondisi daun sebenarnya."},
{n:41,type:"mcq",micro:"AI sempit (narrow)",q:"Hampir semua AI yang ada sekarang adalah 'AI sempit', artinya...",options:["Hanya bisa dipakai oleh orang-orang tertentu yang punya izin khusus dari pembuatnya saja","Ukuran filenya kecil sehingga muat disimpan dalam ponsel sederhana yang tidak berlayar besar","Ahli pada satu jenis tugas saja (misalnya mengenali wajah), dan tidak bisa langsung mengerjakan tugas lain"],answer:2,explain:"AI sempit hebat pada tugas spesifik yang dilatihkan. AI 'umum' yang secakap manusia di banyak hal sekaligus belum ada.",hint:"Bisakah AI catur juga menyetir mobil tanpa dilatih ulang?"},
{n:42,type:"mcq",micro:"AI umum (general)",q:"'AI umum' (AGI) merujuk pada gagasan AI yang...",options:["Bisa belajar dan menangani beragam tugas baru selayaknya manusia — masih bersifat hipotetis","Sudah terpasang di ponsel dan komputer kita dan dipakai banyak orang di rumah setiap harinya","Hanya mampu bermain satu jenis gim dengan sangat mahir dan tidak dapat mengerjakan tugas lain"],answer:0,explain:"AGI adalah konsep AI seluwes manusia. Para ahli berbeda pendapat apakah dan kapan itu mungkin.",hint:"Apakah kita sudah punya satu AI yang bisa melakukan semua hal yang bisa dilakukan manusia?"},
{n:43,type:"mcq",micro:"Klasifikasi",q:"Tugas 'menentukan apakah ulasan film bernada positif atau negatif' adalah contoh...",options:["Pembuatan gambar — menggambar sesuatu yang baru dari deskripsi","Klasifikasi — menempatkan masukan ke dalam salah satu kategori","Penerjemahan — mengubah teks dari satu bahasa ke bahasa lain"],answer:1,explain:"Klasifikasi memilih satu label dari beberapa kategori: spam/bukan, positif/negatif, jenis hewan.",hint:"Berapa banyak kotak kategori yang tersedia untuk hasilnya?"},
{n:44,type:"mcq",micro:"Regresi / prediksi angka",q:"Memprediksi harga sebuah rumah dalam rupiah dari luas dan lokasinya adalah tugas...",options:["Pengenalan suara","Klasifikasi ke dua kategori","Prediksi nilai angka (regresi)"],answer:2,explain:"Kalau keluarannya berupa angka pada rentang (harga, suhu, waktu tempuh), itu tugas regresi, bukan klasifikasi.",hint:"Apakah jawabannya 'kategori A/B' atau 'sebuah bilangan'?"},
{n:45,type:"mcq",micro:"Model bahasa besar",q:"AI percakapan seperti chatbot modern pada dasarnya adalah model yang...",options:["Memprediksi teks berikutnya kata demi kata berdasarkan pola dari teks dalam jumlah sangat besar","Menelepon seorang manusia di balik layar untuk meminta jawaban setiap kali ditanya sesuatu","Menyimpan satu jawaban tetap yang sudah ditulis sebelumnya untuk tiap pertanyaan yang mungkin ada"],answer:0,explain:"Model bahasa besar menghasilkan jawaban dengan berulang kali memprediksi potongan kata berikutnya yang paling masuk akal.",hint:"Bagaimana papan ketik prediktif bekerja — dan bayangkan itu diperbesar ribuan kali."},
{n:46,type:"mcq",micro:"AI generatif",q:"'AI generatif' berbeda dari pengklasifikasi karena ia...",options:["Hanya memberi label ya atau tidak pada setiap data yang masuk","Menghasilkan konten baru seperti teks, gambar, atau musik","Mengurutkan data lama menurut tanggal dan nomor urutnya"],answer:1,explain:"AI generatif membuat keluaran baru (karangan, ilustrasi, lagu) alih-alih sekadar memilih kategori.",hint:"Membuat sesuatu yang baru vs memilah yang sudah ada."},
{n:47,type:"mcq",micro:"Pelatihan vs penggunaan",q:"Fase 'pelatihan' dan fase 'penggunaan (inferensi)' sebuah AI berbeda: pelatihan adalah saat...",options:["Model dimatikan lalu diganti dengan yang baru — biasanya setiap hari dan hanya butuh sedikit sumber daya","Model dipakai menjawab pertanyaan pengguna — biasanya berulang kali dan tanpa mengubah pola internalnya","Model menyesuaikan pola internalnya dari data — biasanya sekali di awal dan butuh banyak sumber daya"],answer:2,explain:"Pelatihan membentuk model (mahal, dilakukan pembuatnya). Penggunaan adalah menjalankan model jadi untuk menjawab (lebih ringan, dilakukan tiap hari).",hint:"Kapan model 'belajar', dan kapan ia hanya 'bekerja'?"},
{n:48,type:"mcq",micro:"AI tidak otomatis diperbarui",q:"Sebuah model bahasa dilatih dengan teks sampai tahun tertentu. Tentang kejadian setelah itu, model...",options:["Mungkin tidak tahu, kecuali diberi informasi baru atau dihubungkan ke sumber terkini","Bisa melihat masa depan lewat pola data, sehingga mengetahui kejadian sesudah pelatihannya","Tahu kejadian terbaru dari seluruh dunia karena AI terus membaca berita setiap detik"],answer:0,explain:"Pengetahuan model terbatas pada data pelatihannya. Kejadian baru di luar itu tidak otomatis diketahuinya.",hint:"Kalau 'buku pelajaran' AI dicetak tahun lalu, apakah ia tahu berita minggu ini?"},
{n:49,type:"classify",micro:"Mengelompokkan tugas AI",q:"Kelompokkan tiap tugas sebagai 'Klasifikasi', 'Prediksi angka', atau 'Generatif'.",items:["Menandai komentar sebagai 'kasar' atau 'sopan'","Memperkirakan berapa menit lagi bus tiba","Menulis puisi empat baris tentang hujan","Menebak jenis penyakit tanaman dari foto daun"],groups:["Klasifikasi","Prediksi angka","Generatif"],answer:{"Klasifikasi":["Menandai komentar sebagai 'kasar' atau 'sopan'","Menebak jenis penyakit tanaman dari foto daun"],"Prediksi angka":["Memperkirakan berapa menit lagi bus tiba"],"Generatif":["Menulis puisi empat baris tentang hujan"]},explain:"Klasifikasi memilih kategori; prediksi angka menghasilkan bilangan; generatif membuat konten baru.",hint:"Apakah hasilnya kategori, angka, atau karya baru?"},
{n:50,type:"mcq",micro:"Agen AI",q:"Sebuah 'agen AI' adalah sistem yang...",options:["Hanya menjawab satu pertanyaan lalu berhenti, tanpa mencari informasi, memakai alat, atau mengulang langkah untuk mencapai tujuan","Tidak hanya menjawab, tapi juga mengambil langkah-langkah tindakan untuk mencapai tujuan (mencari, memakai alat, mengulang)","Dijalankan oleh manusia di balik layar yang mengetik setiap jawaban satu per satu, bukan oleh program yang mengambil tindakan"],answer:1,explain:"Agen menggabungkan model dengan kemampuan bertindak: memakai alat, menjalankan langkah, memeriksa hasil, dan menyesuaikan rencana.",hint:"Menjawab satu kali vs mengerjakan tugas bertahap sampai selesai."},
{n:51,type:"open",micro:"Memilih jenis AI untuk sebuah masalah",q:"Sekolah ingin sistem yang otomatis memisahkan foto kegiatan ke dalam album 'olahraga', 'seni', dan 'upacara'. Jenis tugas AI apa ini, data latih seperti apa yang dibutuhkan, dan bagaimana cara mengujinya?",explain:"Jawaban baik mengenali ini sebagai klasifikasi multi-kelas, menyebut kebutuhan data berlabel yang beragam, dan pengujian pada data terpisah dengan ukuran ketepatan.",hint:"Berapa kategori keluarannya, dan bagaimana kamu tahu modelnya bekerja tanpa hanya menghafal?",sample:"Ini tugas klasifikasi gambar dengan tiga kategori. Data latih: ratusan hingga ribuan foto kegiatan sekolah yang sudah dikelompokkan orang ke 'olahraga', 'seni', 'upacara', mencakup berbagai lokasi, waktu, dan sudut. Pengujian: sisihkan sebagian foto berlabel yang TIDAK dipakai berlatih, jalankan model padanya, dan hitung berapa persen yang dikategorikan dengan benar; periksa juga jenis kesalahan yang paling sering (misalnya seni tertukar dengan upacara)."},
{n:52,type:"mcq",micro:"AI dan aturan bisa digabung",q:"Sistem nyata sering menggabungkan AI dengan aturan buatan manusia. Contohnya, filter spam AI dipadukan dengan aturan 'selalu izinkan email dari kontak tersimpan'. Ini berguna karena...",options:["Aturan hanya memperlambat AI tanpa manfaat berarti, sehingga aturan tegas sebaiknya dihindari dalam sistem yang dipakai nyata","Aturan buatan manusia menggantikan AI sepenuhnya, jadi bagian AI di dalam sistem itu hanya hiasan dan tidak berfungsi","Aturan tegas menjamin perilaku penting yang tidak boleh salah, sementara AI menangani kasus yang rumit dan berubah-ubah"],answer:2,explain:"Aturan memberi jaminan dan kendali; AI memberi keluwesan. Banyak sistem terbaik memakai keduanya.",hint:"Kapan kamu ingin kepastian mutlak, dan kapan kamu ingin keluwesan?"},
{n:53,type:"mcq",micro:"Data pelatihan berasal dari manusia",q:"Ketika model bahasa 'tahu' banyak fakta, sumber utamanya adalah...",options:["Teks yang ditulis manusia (buku, artikel, situs) yang menjadi data pelatihannya","Sinyal dari luar angkasa yang ditangkap antena besar lalu disalin ke model","Pengamatan langsung model saat berjalan keliling dunia nyata"],answer:0,explain:"Model bahasa menyerap pola dari tulisan manusia. 'Pengetahuannya' adalah cerminan tulisan-tulisan itu, lengkap dengan kekeliruannya.",hint:"Apa yang dibaca model selama pelatihan?"},
{n:54,type:"mcq",micro:"Batas kemampuan",q:"Manakah yang PALING sulit dijamin benar oleh model bahasa saat ini?",options:["Meniru gaya penulisan tertentu, seperti gaya surat resmi atau gaya cerita anak","Memberi angka statistik spesifik atau kutipan persis tanpa akses ke sumber terpercaya","Membuat daftar ide untuk judul karangan atau nama kelompok belajar yang baru"],answer:1,explain:"Detail presisi (angka, tanggal, kutipan) rawan keliru karena model memprediksi teks yang 'terdengar benar', bukan mengambil dari basis data terverifikasi.",hint:"Mana yang butuh ketepatan persis, bukan sekadar 'terdengar masuk akal'?"},
{n:55,type:"mcq",micro:"Mengapa jawaban AI bisa berbeda tiap kali",q:"Kamu menanyakan hal yang sama dua kali dan mendapat jawaban yang sedikit berbeda. Ini karena...",options:["Pertanyaanmu rusak setelah dikirim, sehingga mesin memahaminya dengan cara yang berbeda tiap kali","Dua AI yang berbeda diam-diam berdebat di dalam aplikasi, lalu salah satunya memberi jawaban","Banyak model sengaja menambah sedikit keacakan saat memilih kata, sehingga keluarannya bervariasi"],answer:2,explain:"Model generatif sering memilih di antara beberapa kata yang mungkin dengan sedikit unsur acak, membuat jawaban tidak selalu identik.",hint:"Apakah AI selalu memilih satu-satunya kata 'terbaik', atau kadang variasi yang hampir sama baiknya?"},
{n:56,type:"tf",micro:"AI meniru pola, bukan sumber kebenaran",q:"Benar atau Salah: Jika jawaban model bahasa terdengar lancar, percaya diri, dan meyakinkan, itu berarti isinya pasti akurat.",answer:false,explain:"Kelancaran bahasa dan kebenaran fakta adalah dua hal berbeda. Model dilatih menghasilkan teks yang terdengar wajar, jadi ia bisa sangat fasih sekaligus keliru.",hint:"Apakah 'terdengar pintar' sama dengan 'benar'?"},
{n:57,type:"mcq",micro:"Personalisasi",q:"Dua orang bertanya 'film apa yang bagus?' ke aplikasi yang sama dan mendapat saran berbeda. Kemungkinan besar karena...",options:["AI mempertimbangkan riwayat dan pola tiap pengguna (personalisasi)","Salah satu dari keduanya sedang berbohong kepada aplikasi","Aplikasinya rusak dan memberi jawaban acak"],answer:0,explain:"Sistem rekomendasi menyesuaikan keluaran dengan data tiap pengguna, jadi jawabannya berbeda-beda.",hint:"Informasi apa yang aplikasi punya tentang tiap orang?"},
{n:58,type:"mcq",micro:"AI butuh sumber daya",q:"Melatih model besar membutuhkan...",options:["Hanya sedikit sumber daya, karena model bisa dilatih tanpa komputer, listrik, maupun data","Banyak daya komputasi, listrik, dan data — sehingga mahal dan berdampak lingkungan","Hanya satu laptop biasa yang dinyalakan lima menit, lalu modelnya langsung selesai dilatih"],answer:1,explain:"Model besar butuh ribuan prosesor khusus berhari-hari. Ini menimbulkan biaya finansial dan jejak energi yang nyata.",hint:"Apakah 'mengajari' sesuatu dari miliaran contoh itu murah?"},
{n:59,type:"mcq",micro:"Manusia dalam lingkaran",q:"'Manusia dalam lingkaran' (human-in-the-loop) berarti...",options:["AI menggantikan semua pekerja manusia sehingga tidak ada lagi orang yang bekerja di perusahaan","Manusia dilarang menyentuh sistem AI sedikit pun, sehingga seluruh keputusan diserahkan pada mesin","Seorang manusia memeriksa atau menyetujui keputusan penting AI sebelum dijalankan"],answer:2,explain:"Untuk keputusan berisiko (medis, hukum, keuangan), praktik yang baik menempatkan manusia untuk meninjau keluaran AI.",hint:"Siapa yang menekan tombol 'setujui' pada keputusan yang serius?"},
{n:60,type:"open",micro:"Menjelaskan 'AI hanya prediksi pola'",q:"Seorang teman berkata 'AI chatbot itu tahu segalanya dan selalu benar'. Tulis penjelasan singkat (3–4 kalimat) yang mengoreksi anggapan ini menggunakan gagasan 'prediksi pola' dan 'data pelatihan'.",explain:"Penjelasan baik menyebut: AI memprediksi pola bukan memahami; pengetahuannya berasal dari (dan dibatasi oleh) data pelatihan; kelancaran bukan jaminan kebenaran.",hint:"Pakai kata 'memprediksi', 'pola', 'data pelatihan', dan 'perlu diperiksa'.",sample:"Contoh: 'Chatbot tidak benar-benar 'tahu' — ia menghasilkan jawaban dengan memprediksi kata demi kata berdasarkan pola dari teks yang dipakai melatihnya. Kalau teks itu mengandung kekeliruan, atau pertanyaannya soal hal di luar data pelatihannya, jawabannya bisa salah meski terdengar sangat meyakinkan. Karena itu, untuk hal penting kita tetap perlu memeriksa jawabannya dengan sumber tepercaya.'"},
{n:61,type:"mcq",micro:"Bias masuk, bias keluar",q:"Sebuah AI penyaring lamaran kerja dilatih dari data 10 tahun terakhir sebuah perusahaan yang jarang merekrut perempuan untuk peran teknis. Kemungkinan besar AI itu akan...",options:["Meniru pola lama dan memberi nilai lebih rendah pada pelamar perempuan, karena itulah pola dalam datanya","Menolak seluruh pelamar dengan acak, karena modelnya tidak membaca data lamaran dari perusahaan itu","Memperbaiki ketidakadilan masa lalu dengan sendirinya, karena komputer bersifat netral terhadap data"],answer:0,explain:"AI belajar pola dari data historis. Kalau data itu mengandung ketidakadilan, AI cenderung mengulanginya, bahkan memperkuatnya.",hint:"Pola apa yang ada di dalam data 10 tahun itu?"},
{n:62,type:"tf",micro:"Data 'netral' itu jarang",q:"Benar atau Salah: Karena data pelatihan dikumpulkan dari dunia nyata yang penuh ketimpangan, data yang benar-benar bebas bias sangat sulit didapat.",answer:true,explain:"Data mencerminkan dunia dan pilihan orang yang mengumpulkannya. Menyadari dan memeriksa bias lebih realistis daripada berharap data sempurna.",hint:"Dari mana data berasal, dan apakah dunia itu sudah adil?"},
{n:63,type:"mcq",micro:"Korelasi bukan pemahaman",q:"Sebuah AI medis belajar bahwa foto rontgen dari 'rumah sakit A' lebih sering berlabel 'sakit parah'. Ia mungkin mulai menebak berdasarkan...",options:["Pemahaman mendalam tentang penyakit seperti seorang dokter ahli yang sudah bertahun-tahun bekerja","Petunjuk yang tidak relevan seperti gaya alat rontgen rumah sakit itu, bukan kondisi pasien","Nasihat langsung dari dokter senior yang berbisik kepada AI setiap kali sebuah foto rontgen masuk"],answer:1,explain:"AI menangkap korelasi apa pun yang membantu menebak di data latih, termasuk petunjuk 'curang' yang tidak berhubungan dengan sebab sebenarnya.",hint:"Apa lagi yang 'selalu berbeda' antara rumah sakit A dan lainnya, selain kondisi pasien?"},
{n:64,type:"mcq",micro:"Halusinasi",q:"Ketika model bahasa dengan percaya diri menghasilkan fakta, nama buku, atau kutipan yang sebenarnya tidak ada, ini sering disebut...",options:["Kebohongan yang disengaja — model memang berniat menipu penggunanya","Kesalahan ketik — model keliru menekan huruf saat mengetik jawabannya","'Halusinasi' — keluaran yang terdengar masuk akal tapi tidak berdasar"],answer:2,explain:"Model memprediksi teks yang pola-nya pas, sehingga kadang 'mengarang' detail yang terdengar meyakinkan. Perlu verifikasi mandiri.",hint:"Terdengar benar + tidak nyata = istilahnya apa?"},
{n:65,type:"mcq",micro:"Kapan TIDAK mengandalkan AI sepenuhnya",q:"Untuk keputusan mana AI sebaiknya HANYA membantu, dengan keputusan akhir tetap di tangan manusia?",options:["Menentukan apakah seorang pasien mendapat operasi besar","Mengurutkan daftar belanja bulanan dari harga terendah","Memilih lagu latar untuk video ulang tahun keluarga"],answer:0,explain:"Semakin besar dampaknya pada kehidupan, kesehatan, hak, atau keuangan seseorang, semakin penting penilaian dan tanggung jawab manusia.",hint:"Mana yang taruhannya nyawa atau hak seseorang?"},
{n:66,type:"tf",micro:"AI meyakinkan meski salah",q:"Benar atau Salah: Salah satu risiko AI adalah nada jawabannya tetap tenang dan meyakinkan bahkan ketika isinya keliru, sehingga orang mudah percaya begitu saja.",answer:true,explain:"AI tidak menandai keraguannya seperti manusia. Gaya yang selalu percaya diri membuat kesalahan lebih sulit dikenali.",hint:"Apakah AI terdengar ragu saat ia sebenarnya salah?"},
{n:67,type:"mcq",micro:"Otomatisasi vs otonomi",q:"'Otomatisasi' (mesin menjalankan tugas yang ditetapkan) berbeda dari 'otonomi penuh' (mesin menetapkan tujuannya sendiri). AI saat ini...",options:["Sepenuhnya otonom, memilih sendiri tujuannya, dan menentukan apa yang penting tanpa arahan manusia","Menjalankan tujuan yang diberikan manusia; ia tidak memilih sendiri apa yang penting untuk dikejar","Sudah mengembangkan keinginan dan perasaannya sendiri, sehingga ia memutuskan tujuan berdasarkan kemauannya"],answer:1,explain:"AI bisa sangat mandiri dalam melaksanakan tugas, tapi tujuan dan nilainya berasal dari manusia yang merancangnya.",hint:"Siapa yang memutuskan APA yang harus dikejar AI?"},
{n:68,type:"mcq",micro:"Privasi dan data",q:"Saat kamu memakai layanan AI gratis, sesuatu yang bijak untuk ditanyakan adalah...",options:["Siapa orang pertama yang menemukan komputer, dan di tahun berapa layanan itu pertama kali diluncurkan ke publik","Apakah warna logo layanannya cocok dengan warna favoritku, dan apakah tampilannya enak dilihat di layar ponsel","Apakah percakapan atau data yang kuunggah disimpan dan dipakai untuk melatih model, dan apakah aku nyaman dengan itu"],answer:2,explain:"Data yang kamu masukkan bisa disimpan atau dipakai lebih lanjut. Membaca kebijakan privasi dan menghindari berbagi informasi sensitif itu penting.",hint:"Ke mana perginya apa yang kamu ketik ke layanan itu?"},
{n:69,type:"mcq",micro:"AI dan pekerjaan",q:"Pandangan yang paling seimbang tentang AI dan pekerjaan adalah...",options:["AI kemungkinan mengubah banyak pekerjaan — mengotomasi sebagian tugas, menciptakan tugas baru, dan menggeser keterampilan yang dibutuhkan","AI hanya akan memengaruhi pekerjaan para ahli komputer, sedangkan pekerjaan lain tetap berjalan seperti sebelumnya dan tidak berubah","AI akan menggantikan hampir seluruh pekerjaan manusia dalam waktu singkat, sehingga tidak ada tugas baru yang muncul bagi para pekerja"],answer:0,explain:"Sejarah teknologi menunjukkan pergeseran, bukan sekadar penghapusan: beberapa tugas hilang, yang lain muncul, dan banyak peran berubah isinya.",hint:"Apakah teknologi masa lalu menghapus kerja sama sekali, atau mengubah bentuknya?"},
{n:70,type:"order",micro:"Memeriksa klaim AI",q:"Urutkan langkah menilai sebuah artikel berjudul 'AI Kini Bisa Merasakan Emosi'.",items:["Baca apa yang sebenarnya dilakukan sistem itu, bukan hanya judulnya","Tanya: apakah 'merasakan' berarti benar-benar punya perasaan, atau hanya mengenali/menghasilkan kata-kata emosi","Cari sumber independen atau pendapat ahli untuk memeriksa klaim tersebut","Simpulkan seberapa besar klaim itu dilebih-lebihkan"],answer:[0,1,2,3],explain:"Judul sering berlebihan. Periksa mekanisme sebenarnya, perjelas istilah, cek sumber lain, lalu nilai.",hint:"Mulai dari 'apa yang sebenarnya terjadi', bukan dari judul."},
{n:71,type:"mcq",micro:"Anthropomorfisme",q:"Menyebut AI 'ingin', 'berpikir', atau 'takut' berguna sebagai bahasa sehari-hari, tapi bisa menyesatkan karena...",options:["Kata-kata itu terlalu panjang untuk diucapkan sehingga membuat percakapan menjadi lambat dan membosankan","Membuat kita mengira AI punya pengalaman batin, padahal ia memproses pola tanpa kesadaran","Membuat AI tersinggung dan marah sehingga ia menolak bekerja dan mematikan dirinya sendiri nanti"],answer:1,explain:"Bahasa 'seperti manusia' itu praktis, tapi mengaburkan bahwa AI tidak punya perasaan, keinginan, atau kesadaran seperti kita.",hint:"Apakah termostat benar-benar 'ingin' ruangan hangat?"},
{n:72,type:"mcq",micro:"Data langka membuat AI lemah",q:"Sebuah AI pengenal suara bekerja buruk untuk penutur logat daerah tertentu. Penjelasan paling mungkin:",options:["AI sengaja dibuat tidak menyukai logat itu oleh pembuatnya, jadi suara tersebut ditolak oleh modelnya","Logat itu termasuk 'salah' menurut tata bahasa, sehingga model harus menolak mengenali ucapannya","Data latih berisi sangat sedikit contoh suara dengan logat itu, jadi model kurang belajar polanya"],answer:2,explain:"Kelompok yang kurang terwakili dalam data latih sering mendapat layanan AI yang lebih buruk — masalah keadilan yang nyata.",hint:"Seberapa banyak contoh logat itu ada di data latih?"},
{n:73,type:"tf",micro:"Menguji AI sebelum mempercayainya",q:"Benar atau Salah: Untuk hal penting, sebaiknya kita langsung mempercayai keluaran AI tanpa perlu mengujinya pada kasus yang jawabannya sudah kita ketahui.",answer:false,explain:"Sebaiknya diuji dulu. Menjalankan AI pada beberapa kasus yang kamu tahu jawabannya adalah cara cepat menilai apakah ia bisa diandalkan untuk keperluanmu.",hint:"Bagaimana kamu tahu alat baru bisa dipercaya sebelum mengandalkannya?"},
{n:74,type:"mcq",micro:"AI vs kalkulator untuk hitungan",q:"Untuk perhitungan aritmetika yang panjang dan harus tepat, alat yang lebih dapat diandalkan biasanya...",options:["Kalkulator atau program yang memang dirancang menghitung persis, karena model bahasa bisa keliru pada angka","Model bahasa lain yang lebih besar, karena ukuran model otomatis membuat hitungan angka jadi tepat","Meminta teman menebak hasilnya dengan cepat, karena tebakan manusia lebih teliti untuk hitungan panjang"],answer:0,explain:"Model bahasa memprediksi teks, bukan menghitung. Untuk ketepatan angka, pakai alat hitung khusus (atau AI yang memanggil alat hitung).",hint:"Alat mana yang tugas utamanya memang berhitung persis?"},
{n:75,type:"mcq",micro:"Konteks memengaruhi jawaban AI",q:"Memberi AI konteks yang jelas ('Aku murid kelas 6, jelaskan sederhana, dalam 3 kalimat') umumnya...",options:["Tidak berpengaruh pada jawaban karena AI mengabaikan isi permintaan","Membantu AI menghasilkan jawaban yang lebih sesuai kebutuhanmu","Membuat AI berhenti bekerja karena terlalu banyak informasi dari kamu"],answer:1,explain:"Keluaran AI sangat dipengaruhi masukan. Instruksi yang spesifik tentang tujuan, audiens, dan format meningkatkan kualitas jawaban.",hint:"Apakah pertanyaan yang samar atau yang jelas menghasilkan jawaban lebih berguna?"},
{n:76,type:"mcq",micro:"Siapa memeriksa keluaran",q:"Kamu memakai AI untuk membantu menulis laporan sains. Tanggung jawab atas kebenaran isi laporan itu ada pada...",options:["Gurumu, karena guru yang memberi tugas sehingga guru yang harus memeriksa isi laporannya","AI-nya, karena AI yang menulis kalimat dan menyusun fakta sehingga kamu tidak perlu memeriksa","Kamu, sebagai orang yang menyerahkan laporan itu — kamu wajib memeriksa dan memahaminya"],answer:2,explain:"AI adalah alat bantu. Orang yang menggunakan dan menyerahkan hasil tetap bertanggung jawab memverifikasi dan memahaminya.",hint:"Nama siapa yang tertera di laporan itu?"},
{n:77,type:"tf",micro:"AI dapat memperkuat gelembung informasi",q:"Benar atau Salah: Sistem rekomendasi yang terus menyajikan konten serupa dengan yang kita sukai bisa mempersempit sudut pandang kita seiring waktu.",answer:true,explain:"Umpan yang dipersonalisasi bisa menciptakan 'gelembung': kita makin jarang menemui pandangan atau informasi yang berbeda.",hint:"Kalau kamu hanya ditunjukkan hal yang kamu setujui, apa yang terjadi pada wawasanmu?"},
{n:78,type:"mcq",micro:"Menilai kapan AI 'cukup baik'",q:"AI penerjemah membantu kamu memahami menu di negara asing. Tingkat kesalahan kecil di sini...",options:["Umumnya dapat diterima karena taruhannya rendah dan kamu bisa memeriksa ulang bila ragu","Berarti AI tidak berguna untuk menerjemahkan, jadi sebaiknya tidak dipakai di situasi begini","Tidak dapat diterima, jadi jangan memakai AI untuk urusan yang berhubungan dengan bahasa"],answer:0,explain:"Kecocokan pemakaian AI bergantung pada taruhan. Untuk keperluan santai berisiko rendah, kesalahan kecil bisa ditoleransi; untuk kontrak hukum, tidak.",hint:"Apa akibat terburuk kalau terjemahan menu sedikit meleset?"},
{n:79,type:"mcq",micro:"Transparansi",q:"Mengapa penting mengetahui bahwa sebuah keputusan (misalnya penolakan pinjaman) dibuat 'dengan bantuan AI'?",options:["Supaya masyarakat dapat memuji AI dan berterima kasih langsung kepada mesin yang membuat keputusan itu","Supaya orang yang terdampak bisa mempertanyakan, meminta penjelasan, dan mengajukan keberatan atas keputusan itu","Tidak penting, karena yang menentukan hanya hasil akhirnya dan bukan cara memutuskannya atau pihak yang terlibat"],answer:1,explain:"Transparansi memungkinkan akuntabilitas: orang berhak tahu bagaimana keputusan yang memengaruhi mereka dibuat dan bisa menggugatnya.",hint:"Kalau kamu ditolak, apa yang ingin kamu ketahui?"},
{n:80,type:"open",micro:"Menimbang penggunaan AI",q:"Sebuah sekolah mempertimbangkan memakai AI untuk menilai esai siswa secara otomatis. Sebutkan dua manfaat yang mungkin dan dua risiko/kekhawatiran, lalu beri satu rekomendasi bagaimana memakainya secara bertanggung jawab.",explain:"Jawaban baik menimbang manfaat efisiensi vs risiko bias, ketergantungan, dan privasi, lalu mengusulkan pemakaian dengan pengawasan manusia dan transparansi.",hint:"Pikirkan kecepatan vs keadilan, dan siapa yang mengambil keputusan akhir.",sample:"Manfaat: (1) umpan balik cepat untuk latihan, sehingga siswa bisa merevisi lebih sering; (2) meringankan beban penilaian rutin guru. Risiko: (1) AI bisa bias terhadap gaya menulis tertentu atau menghukum ide kreatif yang tidak biasa; (2) siswa dan guru bisa terlalu bergantung dan kehilangan penilaian mendalam; ada juga soal privasi tulisan siswa. Rekomendasi: pakai AI hanya untuk umpan balik latihan (bukan nilai rapor final), selalu dengan guru meninjau, jelaskan ke siswa bahwa AI dipakai, dan pantau apakah ada kelompok yang dirugikan."},
{n:81,type:"mcq",micro:"Membongkar klaim 'AI yang memutuskan'",q:"Berita: 'AI menolak 2.000 pengajuan bantuan sosial bulan ini.' Cara paling tepat memahami kalimat ini:",options:["AI bertindak sendirian melawan keinginan lembaga itu tanpa pernah dirancang atau diatur manusia, sehingga lembaga itu tidak terkait dengan penolakannya","AI sendiri yang bertanggung jawab penuh dan memilih untuk menolak, sedangkan lembaga dan manusia di dalamnya tidak terlibat dan tidak perlu menjelaskan","Sebuah lembaga menggunakan sistem AI, yang dirancang dan diatur oleh manusia, sebagai bagian dari proses penolakan — tanggung jawab tetap pada lembaga itu"],answer:2,explain:"Menyebut 'AI yang memutuskan' menyamarkan pilihan manusia: siapa yang membangun sistem, menetapkan ambang, dan mengizinkannya berjalan tanpa peninjauan.",hint:"Ganti 'AI menolak' dengan 'lembaga X, memakai alat AI, menolak' — apa yang jadi lebih jelas?"},
{n:82,type:"mcq",micro:"Mengenali AI dalam skenario",q:"Manakah yang PALING mungkin BUKAN AI?",options:["Termostat yang menyalakan pemanas saat suhu di bawah 20°C dan mematikannya saat di atas 22°C","Kamera yang mengenali siapa saja yang tampil di foto keluargamu lalu menandai nama mereka secara otomatis","Aplikasi yang menyarikan buku yang panjang menjadi ringkasan pendek dengan menulis kalimat-kalimat baru sendiri"],answer:0,explain:"Termostat sederhana hanya membandingkan angka dengan ambang tetap — aturan langsung, bukan pola yang dipelajari. Dua lainnya mengenali bahasa atau wajah.",hint:"Mana yang bisa dijelaskan dengan satu kalimat 'jika ... maka ...'?"},
{n:83,type:"tf",micro:"AI tidak menghapus kebutuhan berpikir",q:"Benar atau Salah: Memiliki akses ke AI berarti kita tidak perlu lagi belajar membaca kritis, berhitung, atau memeriksa fakta.",answer:false,explain:"Justru sebaliknya: karena AI bisa keliru dengan meyakinkan, keterampilan berpikir kritis dan verifikasi menjadi makin penting, bukan makin tidak perlu.",hint:"Kalau alatmu kadang salah, apakah kamu jadi lebih butuh atau kurang butuh menilai sendiri?"},
{n:84,type:"mcq",micro:"Memilih pakai AI atau tidak",q:"Untuk tugas mana penggunaan AI generatif PALING bermasalah secara etika tanpa pengungkapan?",options:["Menyusun draf awal daftar pertanyaan wawancara yang kamu periksa dan ubah sendiri","Menyerahkan puisi buatan AI ke lomba menulis atas nama sendiri sebagai karya orisinal","Membuat variasi judul poster acara sekolah lalu kamu pilih satu yang paling cocok"],answer:1,explain:"Mengklaim karya AI sebagai buatan sendiri dalam konteks yang menilai orisinalitas adalah bentuk ketidakjujuran. Pemakaian sebagai alat bantu draf umumnya wajar, apalagi bila diungkapkan.",hint:"Di mana orisinalitas penulis justru menjadi inti yang dinilai?"},
{n:85,type:"mcq",micro:"Data pelatihan dan hak cipta",q:"Salah satu perdebatan penting tentang AI generatif adalah...",options:["Warna antarmuka yang paling baik dan paling nyaman dilihat mata oleh semua pengguna aplikasi itu","Apakah komputer boleh dibiarkan menyala di malam hari atau harus dimatikan setiap malam sebelum tidur","Apakah adil dan sah melatih model dari karya (tulisan, gambar, musik) orang lain tanpa izin atau kompensasi"],answer:2,explain:"Model generatif belajar dari karya manusia dalam jumlah besar. Siapa yang berhak atas nilai yang dihasilkan, dan bagaimana pembuat asli diperlakukan, masih diperdebatkan secara hukum dan etika.",hint:"Dari karya siapa model belajar menggambar 'gaya' tertentu?"},
{n:86,type:"order",micro:"Menggunakan AI secara bertanggung jawab untuk tugas",q:"Urutkan langkah memakai AI untuk membantu riset tugas sekolah dengan jujur dan aman.",items:["Perjelas dulu apa yang kamu butuhkan dan apa yang sudah kamu ketahui","Pakai AI untuk menjelaskan konsep atau memberi arah, bukan untuk menyalin jawaban mentah-mentah","Periksa setiap fakta penting dari AI dengan sumber tepercaya yang independen","Tulis dengan kata-katamu sendiri dan cantumkan bahwa kamu memakai bantuan AI bila diminta"],answer:[0,1,2,3],explain:"Perjelas kebutuhan → gunakan AI untuk memahami, bukan menyontek → verifikasi fakta → hasil akhir tetap karyamu, dengan pengungkapan yang jujur.",hint:"Mulai dari memahami kebutuhanmu sendiri; verifikasi datang sebelum menyerahkan."},
{n:87,type:"mcq",micro:"Menafsirkan skor keyakinan",q:"Sebuah AI diagnosis kulit memberi 'melanoma: 55%, tahi lalat biasa: 45%'. Tindakan paling bijak:",options:["Perlakukan sebagai sinyal untuk segera memeriksakan diri ke dokter kulit, bukan sebagai vonis maupun sebagai izin untuk tenang","Yakin 100% bahwa itu melanoma, lalu panik dan menunggu berminggu-minggu sebelum bertanya kepada tenaga kesehatan di puskesmas","Abaikan hasilnya karena selisih 55% dan 45% itu kecil, lalu tunggu beberapa bulan untuk melihat apakah bercaknya berubah sendiri"],answer:0,explain:"Keluaran AI berisiko tinggi paling baik dipakai sebagai bahan rujukan yang mendorong tindak lanjut oleh ahli, bukan sebagai keputusan akhir.",hint:"Apa gunanya angka ini — mengakhiri pemeriksaan, atau memicu langkah berikutnya?"},
{n:88,type:"mcq",micro:"Umpan balik memperkuat pola",q:"Sistem rekomendasi berita menampilkan lebih banyak artikel yang kamu klik. Jika kamu iseng mengklik satu judul sensasional...",options:["Sistem hanya mencatat klik pada judul yang panjang, sehingga satu klikan iseng tidak mengubah artikel yang ditampilkan kepadamu di masa mendatang","Sistem bisa menyimpulkan kamu menyukai konten semacam itu dan menampilkannya lebih sering, memperkuat pola meski itu bukan minatmu sebenarnya","Sistem langsung menghapus akunmu karena menganggap satu klikan pada judul sensasional sebagai pelanggaran aturan aplikasi berita"],answer:1,explain:"AI belajar dari perilakumu. Perilaku sesaat bisa membentuk umpan jangka panjang — perhatikan sinyal yang kamu kirim.",hint:"Apa yang 'dipelajari' sistem dari setiap klikmu?"},
{n:89,type:"tf",micro:"AI dan bahasa yang kurang sumber daya",q:"Benar atau Salah: Model AI berkinerja sama baiknya untuk semua bahasa, tidak peduli seberapa banyak teks digital yang tersedia untuk bahasa itu.",answer:false,explain:"Ketersediaan data sangat menentukan. Bahasa dengan banyak teks digital (seperti Inggris) umumnya dilayani lebih baik daripada bahasa daerah dengan sedikit data tertulis — kesenjangan yang perlu diperhatikan.",hint:"Model belajar dari teks — apa yang terjadi bila teks untuk suatu bahasa langka?"},
{n:90,type:"mcq",micro:"Batas 'AI bisa segalanya'",q:"Klaim 'model ini bisa mengerjakan tugas APA PUN' sebaiknya disikapi dengan...",options:["Panik dan khawatir berlebihan, lalu menghindari semua teknologi AI di sekolah dan di rumah","Percaya penuh karena perusahaan besar yang membuatnya, jadi ia benar untuk tugas apa saja","Skeptis sehat: minta bukti pada tugas spesifik, uji sendiri, dan cari tahu di mana ia gagal"],answer:2,explain:"Klaim kemampuan yang luas dan tak berbatas hampir selalu berlebihan. Uji pada kasus nyata yang kamu pahami.",hint:"Bagaimana kamu memeriksa klaim besar — dengan percaya, atau dengan menguji?"},
{n:91,type:"mcq",micro:"AI sebagai penguat, bukan pengganti penilaian",q:"Cara sehat menggambarkan hubungan ideal manusia–AI dalam pekerjaan serius:",options:["AI menangani bagian berulang dan menyodorkan pilihan, sementara manusia menetapkan tujuan, menilai konteks, dan bertanggung jawab atas keputusan","Manusia sebaiknya menjauhi AI dalam pekerjaan serius, sebab hasil AI keliru dan tidak membantu bahkan di bagian yang berulang dan sederhana","AI menggantikan penilaian manusia sepenuhnya, sehingga manusia tidak lagi menetapkan tujuan, menilai konteks, atau bertanggung jawab atas keputusan"],answer:0,explain:"Pembagian peran yang baik: AI memperkuat kapasitas manusia; manusia memegang kemudi soal nilai, konteks, dan pertanggungjawaban.",hint:"Siapa memegang kemudi, siapa membantu mendorong?"},
{n:92,type:"mcq",micro:"Mengenali teks buatan AI",q:"Manakah pernyataan yang paling akurat tentang mendeteksi apakah suatu tulisan dibuat AI?",options:["Dapat dipastikan 100% oleh alat pendeteksi, sehingga tidak ada tulisan manusia yang keliru dituduh sebagai tulisan AI","Sulit dan sering tidak pasti; alat pendeteksi bisa salah menuduh tulisan manusia dan meloloskan tulisan AI","Mudah dilihat dari huruf pertama, karena tulisan AI dan manusia memiliki ciri yang berbeda jelas pada setiap kalimat"],answer:1,explain:"Deteksi teks AI tidak andal. Kebijakan yang menghukum berat berdasarkan alat pendeteksi saja berisiko tidak adil.",hint:"Apakah alat semacam ini memberi jawaban pasti atau perkiraan yang bisa keliru?"},
{n:93,type:"mcq",micro:"Nilai dan tujuan berasal dari manusia",q:"Sebuah AI perekomendasi diberi tujuan 'maksimalkan waktu yang dihabiskan pengguna di aplikasi'. Masalah etis utamanya:",options:["AI gagal mengejar tujuan itu karena komputer tidak dapat menghitung waktu pengguna, sehingga tidak muncul masalah etis","Tujuan itu terlalu sulit dihitung oleh program, jadi masalahnya hanya soal teknis dan tidak terkait kesejahteraan pengguna maupun keputusan manusia","Tujuan itu bisa bertentangan dengan kesejahteraan pengguna (tidur, belajar, hubungan sosial); pilihan tujuan itu sendiri adalah keputusan nilai oleh manusia"],answer:2,explain:"AI mengejar tujuan yang diberikan secara efektif. Karena itu, MEMILIH tujuan yang tepat — dan siapa yang diuntungkan — adalah tanggung jawab etis manusia.",hint:"Kalau AI sangat pandai mengejar tujuannya, seberapa penting memilih tujuan yang benar?"},
{n:94,type:"tf",micro:"AI tidak punya pemahaman moral bawaan",q:"Benar atau Salah: AI tidak memiliki rasa benar dan salah bawaan; perilaku 'beretika' sebuah AI berasal dari aturan, data, dan pembatasan yang dirancang manusia.",answer:true,explain:"Setiap kecenderungan 'baik' pada AI adalah hasil rekayasa manusia: pemilihan data, pelatihan tambahan, aturan, dan uji keamanan.",hint:"Dari mana datangnya batasan 'jangan lakukan X' pada sebuah AI?"},
{n:95,type:"mcq",micro:"Menggunakan AI untuk belajar tanpa merugikan diri",q:"Kamu memakai AI untuk 'menyelesaikan' semua soal latihan matematika tanpa mencoba sendiri. Risiko utamanya:",options:["Kamu melewatkan proses berlatih yang justru membangun kemampuan, sehingga saat ujian tanpa AI kamu kesulitan","Guru akan senang karena semua soal terisi rapi dan nilai tugasmu bagus, jadi kamu belajar jauh lebih banyak","Tidak ada risiko karena hasil AI sudah benar, jadi kamu bisa mengerjakan soal ujian dengan lancar nanti"],answer:0,explain:"AI bisa memberi jawaban, tapi keterampilan tumbuh dari usaha. Memakai AI untuk memahami langkah lebih bermanfaat daripada menyalin hasil.",hint:"Apa tujuan sebenarnya dari soal latihan — jawaban benar, atau kemampuanmu?"},
{n:96,type:"mcq",micro:"Ketahanan terhadap manipulasi",q:"Sebuah unggahan berkata: 'Menurut AI, kabar ini 100% benar, jadi sebarkan.' Respons kritis:",options:["Segera sebarkan ke teman-teman karena AI sudah memastikan kabar itu benar, jadi makin cepat disebarkan makin baik bagi teman-teman kita di grup","AI tidak menjadikan sesuatu benar; periksa sumber aslinya, siapa yang mengunggah, dan apakah 'AI bilang' itu bahkan bisa dibuktikan","Percaya saja karena ada kata 'AI' di dalamnya, sebab sesuatu yang disebut AI terbukti tepat sehingga sumber aslinya tidak perlu dicari"],answer:1,explain:"'AI bilang' sering dipakai untuk memberi kesan otoritas palsu. Verifikasi tetap pada sumber dan bukti, bukan pada label 'AI'.",hint:"Apakah menempelkan kata 'AI' membuat sebuah klaim otomatis benar?"},
{n:97,type:"tf",micro:"Memahami keterbatasan membuat AI lebih berguna",q:"Benar atau Salah: Orang yang memahami cara kerja dan batas AI biasanya bisa memanfaatkannya lebih efektif dan lebih aman daripada yang menganggapnya ajaib atau menakutkan.",answer:true,explain:"Literasi AI — tahu apa yang bisa dan tidak bisa dilakukannya, serta di mana ia rapuh — adalah kunci memakainya dengan bijak.",hint:"Pengguna yang paham alat vs yang menganggapnya sihir — siapa yang lebih aman?"},
{n:98,type:"mcq",micro:"Menilai sistem AI baru",q:"Sekolahmu ditawari 'AI pendeteksi contekan ujian dari rekaman kamera'. Pertanyaan paling penting untuk diajukan lebih dulu:",options:["Apakah ada versi khusus untuk ponsel supaya dapat dipakai di mana saja oleh guru dan siswa, dan apakah memasangnya mudah tanpa ahli","Apakah warna tampilannya dapat disesuaikan dengan selera sekolah, dan apakah logonya bisa diganti dengan lambang sekolah kita di semua halaman","Seberapa sering ia salah menuduh siswa jujur (positif palsu), data siapa yang direkam dan disimpan, dan siapa yang meninjau tuduhannya"],answer:2,explain:"Untuk sistem berisiko tinggi, yang utama adalah tingkat kesalahan (terutama tuduhan palsu), dampak privasi, dan adanya peninjauan manusia serta jalur banding.",hint:"Apa kerugian terbesar bila sistem ini keliru terhadap seorang siswa?"},
{n:99,type:"mcq",micro:"Ringkasan: apa itu AI",q:"Rangkuman satu kalimat yang paling akurat:",options:["AI adalah kumpulan teknik untuk membuat program mengerjakan tugas 'cerdas' dengan mempelajari pola dari data, sangat berguna namun terbatas, keliru, dan bergantung pada pilihan manusia","AI adalah sihir yang tidak dapat dipahami oleh manusia, jadi kita cukup percaya pada jawabannya tanpa memeriksa, tanpa bertanya, dan tanpa mempelajari cara kerjanya sedikit pun","AI adalah komputer yang sudah sadar dan berpikir seperti manusia, memiliki perasaan sendiri, kebal terhadap kesalahan, dan tidak bergantung pada pilihan atau arahan manusia dalam bekerja"],answer:0,explain:"AI adalah alat berbasis pola: kuat untuk tugas tertentu, tidak sadar, bisa salah, dan sepenuhnya dibentuk oleh data serta keputusan manusia.",hint:"Gabungkan: belajar pola dari data + berguna + terbatas + tanggung jawab manusia."},
{n:100,type:"open",micro:"Kapstone: menjelaskan AI ke orang lain",q:"Bayangkan kamu menjelaskan 'apa itu AI' ke adik kelas berusia 8 tahun DAN ke orang dewasa yang skeptis. Tulis dua penjelasan singkat (masing-masing 3–4 kalimat) yang: menyebut bahwa AI belajar pola dari contoh, memberi satu contoh sehari-hari, dan menyebut satu keterbatasan penting. Sesuaikan bahasa untuk tiap pembaca.",explain:"Jawaban baik menjaga inti yang sama (belajar pola dari contoh, contoh nyata, keterbatasan) sambil menyesuaikan kosakata dan kedalaman untuk tiap audiens.",hint:"Pesan intinya sama; yang berubah hanya pilihan kata dan tingkat detail.",sample:"Untuk anak 8 tahun: 'AI itu seperti program komputer yang belajar dengan melihat banyak sekali contoh. Kalau kita tunjukkan ribuan foto kucing, lama-lama ia bisa menebak mana foto kucing yang baru. Tapi ia bisa salah tebak, misalnya mengira anjing kecil sebagai kucing, jadi kita tetap harus mengeceknya.' Untuk orang dewasa skeptis: 'AI modern adalah sistem statistik yang menyimpulkan pola dari data dalam jumlah besar, lalu memakai pola itu untuk memprediksi — misalnya menyaring email spam atau memperkirakan waktu tempuh di aplikasi peta. Ia tidak memahami dunia; ia mencocokkan pola, sehingga bisa keliru dengan sangat meyakinkan, terutama di luar cakupan data latihnya. Karena itu untuk keputusan penting hasilnya perlu diverifikasi dan diawasi manusia.'"},
];
